<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Brittle Star on a Barrel Sponge</title>
  <style>
    * {
      box-sizing: border-box;
    }

    html,
    body {
      width: 100%;
      height: 100%;
      margin: 0;
      overflow: hidden;
      background:
        radial-gradient(circle at 50% 35%, #173847 0%, #091c27 48%, #040b11 100%);
      color: #e8f0ed;
      font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
    }

    #app {
      position: fixed;
      inset: 0;
    }

    canvas {
      display: block;
      width: 100%;
      height: 100%;
      cursor: grab;
      touch-action: none;
    }

    canvas.dragging {
      cursor: grabbing;
    }

    .label {
      position: fixed;
      top: 26px;
      left: 30px;
      z-index: 2;
      pointer-events: none;
      text-shadow: 0 2px 18px rgba(0, 0, 0, 0.55);
    }

    .label h1 {
      margin: 0;
      font-family: Georgia, "Times New Roman", serif;
      font-size: clamp(25px, 3.2vw, 42px);
      font-weight: 400;
      letter-spacing: 0.015em;
    }

    .label p {
      margin: 7px 0 0;
      color: rgba(220, 237, 232, 0.68);
      font-size: 12px;
      letter-spacing: 0.18em;
      text-transform: uppercase;
    }

    .controls {
      position: fixed;
      right: 24px;
      bottom: 22px;
      z-index: 3;
      display: flex;
      gap: 8px;
      align-items: center;
    }

    button {
      border: 1px solid rgba(190, 225, 220, 0.22);
      border-radius: 999px;
      padding: 9px 15px;
      color: #e9f3ef;
      background: rgba(8, 27, 36, 0.68);
      backdrop-filter: blur(12px);
      font: inherit;
      font-size: 12px;
      letter-spacing: 0.05em;
      cursor: pointer;
      transition: background 160ms ease, border-color 160ms ease, transform 160ms ease;
    }

    button:hover {
      background: rgba(24, 61, 73, 0.82);
      border-color: rgba(190, 225, 220, 0.42);
      transform: translateY(-1px);
    }

    .hint {
      position: fixed;
      left: 30px;
      bottom: 27px;
      z-index: 2;
      color: rgba(218, 235, 231, 0.48);
      font-size: 11px;
      letter-spacing: 0.08em;
      pointer-events: none;
    }

    @media (max-width: 600px) {
      .label {
        top: 18px;
        left: 20px;
      }

      .hint {
        left: 20px;
        bottom: 24px;
      }

      .controls {
        right: 16px;
        bottom: 16px;
      }
    }
  </style>
</head>
<body>
  <div id="app"></div>

  <div class="label">
    <h1>Brittle Star</h1>
    <p>Ophiocomina · barrel sponge habitat</p>
  </div>

  <div class="hint">Drag to orbit · Scroll to zoom</div>

  <div class="controls">
    <button id="rotateButton" type="button">Pause rotation</button>
    <button id="resetButton" type="button">Reset view</button>
  </div>

  <script type="module">
    import * as THREE from "https://cdnjs.cloudflare.com/ajax/libs/three.js/0.160.0/three.module.min.js";

    const app = document.getElementById("app");
    const rotateButton = document.getElementById("rotateButton");
    const resetButton = document.getElementById("resetButton");

    // ---------------------------------------------------------------------
    // Renderer, scene, and camera
    // ---------------------------------------------------------------------

    const renderer = new THREE.WebGLRenderer({
      antialias: true,
      alpha: true,
      powerPreference: "high-performance"
    });

    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    renderer.setSize(window.innerWidth, window.innerHeight);
    renderer.outputColorSpace = THREE.SRGBColorSpace;
    renderer.toneMapping = THREE.ACESFilmicToneMapping;
    renderer.toneMappingExposure = 1.12;
    renderer.shadowMap.enabled = true;
    renderer.shadowMap.type = THREE.PCFSoftShadowMap;
    renderer.setClearColor(0x071720, 0);
    renderer.domElement.setAttribute(
      "aria-label",
      "Interactive three-dimensional brittle star draped over a barrel sponge"
    );
    app.appendChild(renderer.domElement);

    const scene = new THREE.Scene();
    scene.fog = new THREE.FogExp2(0x071720, 0.038);

    const camera = new THREE.PerspectiveCamera(
      38,
      window.innerWidth / window.innerHeight,
      0.1,
      100
    );

    const cameraTarget = new THREE.Vector3(0, 2.25, 0);
    let cameraTheta = 0.72;
    let cameraPhi = 1.12;
    let cameraRadius = 11.8;

    function updateCamera() {
      const sinPhi = Math.sin(cameraPhi);

      camera.position.set(
        cameraTarget.x + cameraRadius * sinPhi * Math.sin(cameraTheta),
        cameraTarget.y + cameraRadius * Math.cos(cameraPhi),
        cameraTarget.z + cameraRadius * sinPhi * Math.cos(cameraTheta)
      );

      camera.lookAt(cameraTarget);
    }

    updateCamera();

    // ---------------------------------------------------------------------
    // Lighting
    // ---------------------------------------------------------------------

    scene.add(new THREE.HemisphereLight(0xc5efff, 0x263b2c, 1.45));

    const keyLight = new THREE.DirectionalLight(0xffe0aa, 3.1);
    keyLight.position.set(5.5, 10, 6.5);
    keyLight.castShadow = true;
    keyLight.shadow.mapSize.set(2048, 2048);
    keyLight.shadow.camera.near = 1;
    keyLight.shadow.camera.far = 25;
    keyLight.shadow.camera.left = -7;
    keyLight.shadow.camera.right = 7;
    keyLight.shadow.camera.top = 8;
    keyLight.shadow.camera.bottom = -5;
    keyLight.shadow.bias = -0.00035;
    keyLight.shadow.normalBias = 0.025;
    scene.add(keyLight);

    const rimLight = new THREE.DirectionalLight(0x78cfff, 1.65);
    rimLight.position.set(-6, 5.5, -5);
    scene.add(rimLight);

    const warmFill = new THREE.PointLight(0xffb85f, 12, 12, 2);
    warmFill.position.set(3.5, 3.2, 4.5);
    scene.add(warmFill);

    // ---------------------------------------------------------------------
    // Procedural textures
    // ---------------------------------------------------------------------

    let randomSeed = 918273;

    function random() {
      randomSeed = (randomSeed * 1664525 + 1013904223) >>> 0;
      return randomSeed / 4294967296;
    }

    function createSpongeTextures() {
      const size = 512;
      const colorCanvas = document.createElement("canvas");
      const bumpCanvas = document.createElement("canvas");

      colorCanvas.width = colorCanvas.height = size;
      bumpCanvas.width = bumpCanvas.height = size;

      const colorContext = colorCanvas.getContext("2d");
      const bumpContext = bumpCanvas.getContext("2d");

      colorContext.fillStyle = "#c98235";
      colorContext.fillRect(0, 0, size, size);

      bumpContext.fillStyle = "#777777";
      bumpContext.fillRect(0, 0, size, size);

      // Hundreds of irregular pores, with subtle highlights.
      for (let i = 0; i < 1150; i++) {
        const x = random() * size;
        const y = random() * size;
        const radius = 1 + random() * 6.5;
        const darkness = 0.08 + random() * 0.18;

        colorContext.beginPath();
        colorContext.ellipse(
          x,
          y,
          radius,
          radius * (0.45 + random() * 0.55),
          random() * Math.PI,
          0,
          Math.PI * 2
        );
        colorContext.fillStyle = `rgba(77, 31, 10, ${darkness})`;
        colorContext.fill();

        colorContext.beginPath();
        colorContext.arc(
          x - radius * 0.18,
          y - radius * 0.12,
          radius * 0.28,
          0,
          Math.PI * 2
        );
        colorContext.fillStyle = `rgba(255, 213, 151, ${0.08 + random() * 0.1})`;
        colorContext.fill();

        bumpContext.beginPath();
        bumpContext.ellipse(
          x,
          y,
          radius,
          radius * 0.65,
          random() * Math.PI,
          0,
          Math.PI * 2
        );
        bumpContext.fillStyle = `rgba(45, 45, 45, ${darkness * 1.4})`;
        bumpContext.fill();

        bumpContext.beginPath();
        bumpContext.arc(
          x - radius * 0.2,
          y - radius * 0.15,
          radius * 0.28,
          0,
          Math.PI * 2
        );
        bumpContext.fillStyle = "rgba(220,220,220,0.16)";
        bumpContext.fill();
      }

      const colorTexture = new THREE.CanvasTexture(colorCanvas);
      colorTexture.colorSpace = THREE.SRGBColorSpace;
      colorTexture.wrapS = colorTexture.wrapT = THREE.RepeatWrapping;
      colorTexture.repeat.set(2.4, 2.4);
      colorTexture.anisotropy = renderer.capabilities.getMaxAnisotropy();

      const bumpTexture = new THREE.CanvasTexture(bumpCanvas);
      bumpTexture.wrapS = bumpTexture.wrapT = THREE.RepeatWrapping;
      bumpTexture.repeat.copy(colorTexture.repeat);
      bumpTexture.anisotropy = colorTexture.anisotropy;

      return { colorTexture, bumpTexture };
    }

    function createBrittleStarTexture() {
      const canvas = document.createElement("canvas");
      canvas.width = canvas.height = 256;
      const context = canvas.getContext("2d");

      context.fillStyle = "#e7dfc7";
      context.fillRect(0, 0, 256, 256);

      for (let i = 0; i < 650; i++) {
        const x = random() * 256;
        const y = random() * 256;
        const radius = 0.3 + random() * 1.5;

        context.beginPath();
        context.arc(x, y, radius, 0, Math.PI * 2);
        context.fillStyle = `rgba(91, 78, 54, ${0.025 + random() * 0.08})`;
        context.fill();
      }

      const texture = new THREE.CanvasTexture(canvas);
      texture.colorSpace = THREE.SRGBColorSpace;
      texture.wrapS = texture.wrapT = THREE.RepeatWrapping;
      texture.repeat.set(2, 5);
      texture.anisotropy = renderer.capabilities.getMaxAnisotropy();

      return texture;
    }

    const spongeTextures = createSpongeTextures();
    const starTexture = createBrittleStarTexture();

    // ---------------------------------------------------------------------
    // Materials
    // ---------------------------------------------------------------------

    const spongeMaterial = new THREE.MeshStandardMaterial({
      map: spongeTextures.colorTexture,
      bumpMap: spongeTextures.bumpTexture,
      bumpScale: 0.13,
      roughness: 0.96,
      metalness: 0
    });

    const innerSpongeMaterial = new THREE.MeshStandardMaterial({
      color: 0x3b2419,
      roughness: 1,
      metalness: 0,
      side: THREE.DoubleSide
    });

    const spongeRimMaterial = new THREE.MeshStandardMaterial({
      map: spongeTextures.colorTexture,
      bumpMap: spongeTextures.bumpTexture,
      bumpScale: 0.1,
      roughness: 0.94,
      color: 0xf0b26c
    });

    const starMaterial = new THREE.MeshStandardMaterial({
      map: starTexture,
      bumpMap: starTexture,
      bumpScale: 0.025,
      color: 0xfff1cf,
      roughness: 0.78,
      metalness: 0
    });

    // ---------------------------------------------------------------------
    // Seafloor
    // ---------------------------------------------------------------------

    const floor = new THREE.Mesh(
      new THREE.PlaneGeometry(60, 60),
      new THREE.MeshStandardMaterial({
        color: 0x0b252d,
        roughness: 1,
        metalness: 0
      })
    );

    floor.rotation.x = -Math.PI / 2;
    floor.position.y = 0.015;
    floor.receiveShadow = true;
    scene.add(floor);

    // ---------------------------------------------------------------------
    // Barrel sponge
    // ---------------------------------------------------------------------

    const sponge = new THREE.Group();
    scene.add(sponge);

    const spongeBody = new THREE.Mesh(
      new THREE.CylinderGeometry(3.15, 2.86, 4.8, 72, 12, true),
      spongeMaterial
    );

    spongeBody.position.y = 2.43;
    spongeBody.castShadow = true;
    spongeBody.receiveShadow = true;
    sponge.add(spongeBody);

    // Dark inner wall makes the top opening read as a hollow barrel.
    const innerWall = new THREE.Mesh(
      new THREE.CylinderGeometry(2.66, 2.66, 4.35, 64, 1, true),
      innerSpongeMaterial
    );

    innerWall.position.y = 2.35;
    innerWall.receiveShadow = true;
    sponge.add(innerWall);

    const spongeRim = new THREE.Mesh(
      new THREE.TorusGeometry(2.92, 0.21, 18, 80),
      spongeRimMaterial
    );

    spongeRim.rotation.x = Math.PI / 2;
    spongeRim.position.y = 4.86;
    spongeRim.castShadow = true;
    spongeRim.receiveShadow = true;
    sponge.add(spongeRim);

    const spongeBase = new THREE.Mesh(
      new THREE.CylinderGeometry(2.86, 2.86, 0.16, 72),
      spongeMaterial
    );

    spongeBase.position.y = 0.08;
    spongeBase.castShadow = true;
    spongeBase.receiveShadow = true;
    sponge.add(spongeBase);

    // ---------------------------------------------------------------------
    // Brittle star: compact central disc
    // ---------------------------------------------------------------------

    const star = new THREE.Group();
    scene.add(star);

    const disc = new THREE.Mesh(
      new THREE.SphereGeometry(0.58, 36, 20),
      starMaterial
    );

    disc.scale.y = 0.38;
    disc.position.y = 5.17;
    disc.castShadow = true;
    disc.receiveShadow = true;
    star.add(disc);

    const discTop = new THREE.Mesh(
      new THREE.CylinderGeometry(0.43, 0.51, 0.075, 32),
      starMaterial
    );

    discTop.position.y = 5.365;
    discTop.castShadow = true;
    star.add(discTop);

    // Small calcareous nodules over the disc surface.
    const noduleGeometry = new THREE.SphereGeometry(0.035, 8, 6);

    for (let i = 0; i < 42; i++) {
      const angle = random() * Math.PI * 2;
      const radius = Math.sqrt(random()) * 0.49;
      const normalizedRadius = radius / 0.58;
      const discHeight = 0.2236;

      const y = 5.17 + discHeight * Math.sqrt(Math.max(0, 1 - normalizedRadius * normalizedRadius));

      const nodule = new THREE.Mesh(noduleGeometry, starMaterial);
      nodule.position.set(
        Math.cos(angle) * radius,
        y + 0.012,
        Math.sin(angle) * radius
      );

      const noduleScale = 0.65 + random() * 1.2;
      nodule.scale.set(noduleScale, noduleScale * 0.65, noduleScale);
      nodule.castShadow = true;
      star.add(nodule);
    }

    // ---------------------------------------------------------------------
    // Five long, jointed, differently angled arms
    // ---------------------------------------------------------------------

    const armProfiles = [
      [
        [0.45, 1.05, 1.7, 2.25, 2.85, 3.28, 3.38, 3.28, 2.95],
        [5.18, 5.2, 5.05, 4.65, 4.18, 3.65, 2.95, 2.15, 1.25]
      ],
      [
        [0.47, 1.12, 1.8, 2.4, 2.95, 3.3, 3.4, 3.25, 2.85],
        [5.19, 5.23, 5.08, 4.72, 4.25, 3.55, 2.85, 2.0, 1.12]
      ],
      [
        [0.44, 1.0, 1.65, 2.25, 2.8, 3.2, 3.35, 3.2, 2.8],
        [5.17, 5.2, 5.03, 4.68, 4.2, 3.5, 2.8, 1.95, 1.1]
      ],
      [
        [0.46, 1.15, 1.85, 2.45, 3.0, 3.35, 3.42, 3.25, 2.88],
        [5.2, 5.24, 5.1, 4.75, 4.3, 3.62, 2.9, 2.05, 1.18]
      ],
      [
        [0.43, 1.0, 1.6, 2.2, 2.75, 3.18, 3.32, 3.15, 2.72],
        [5.16, 5.19, 5.04, 4.66, 4.2, 3.55, 2.86, 1.95, 1.1]
      ]
    ];

    const baseAngles = [0.05, 1.0, 1.95, 3.5, 4.55];

    function createArm(profile, angle) {
      const points = profile.map(([radius, height], index) => {
        const radialJitter = (random() - 0.5) * 0.12;
        const heightJitter = (random() - 0.5) * 0.1;

        return new THREE.Vector3(
          Math.cos(angle) * (radius + radialJitter),
          height + heightJitter,
          Math.sin(angle) * (radius + radialJitter)
        );
      });

      const radii = [0.078, 0.067, 0.057, 0.05, 0.043, 0.037, 0.031, 0.027];

      for (let i = 0; i < points.length - 1; i++) {
        const start = points[i];
        const end = points[i + 1];
        const direction = end.clone().sub(start);
        const length = direction.length();

        const segment = new THREE.Mesh(
          new THREE.CylinderGeometry(
            radii[i + 1],
            radii[i],
            length,
            10,
            1,
            false
          ),
          starMaterial
        );

        segment.position.copy(start).add(end).multiplyScalar(0.5);
        segment.quaternion.setFromUnitVectors(
          new THREE.Vector3(0, 1, 0),
          direction.normalize()
        );

        segment.castShadow = true;
        segment.receiveShadow = true;
        star.add(segment);
      }

      // Slightly enlarged joints emphasize the brittle star's segmented anatomy.
      const jointRadii = [0.09, 0.082, 0.073, 0.064, 0.055, 0.048, 0.041, 0.034];

      points.forEach((point, index) => {
        if (index === 0 || index === points.length - 1) return;

        const joint = new THREE.Mesh(
          new THREE.SphereGeometry(jointRadii[index], 14, 10),
          starMaterial
        );

        joint.position.copy(point);
        joint.scale.y = 0.88;
        joint.castShadow = true;
        joint.receiveShadow = true;
        star.add(joint);
      });
    }

    armProfiles.forEach((profile, armIndex) => {
      createArm(
        profile,
        baseAngles[armIndex] + (random() - 0.5) * 0.16
      );
    });

    // ---------------------------------------------------------------------
    // Subtle marine snow in the background
    // ---------------------------------------------------------------------

    const marineSnowCount = 180;
    const marineSnowPositions = new Float32Array(marineSnowCount * 3);

    for (let i = 0; i < marineSnowCount; i++) {
      marineSnowPositions[i * 3] = (random() - 0.5) * 22;
      marineSnowPositions[i * 3 + 1] = 0.3 + random() * 8;
      marineSnowPositions[i * 3 + 2] = (random() - 0.5) * 22;
    }

    const marineSnowGeometry = new THREE.BufferGeometry();
    marineSnowGeometry.setAttribute(
      "position",
      new THREE.BufferAttribute(marineSnowPositions, 3)
    );

    const marineSnow = new THREE.Points(
      marineSnowGeometry,
      new THREE.PointsMaterial({
        color: 0xa7c8c8,
        size: 0.025,
        transparent: true,
        opacity: 0.28,
        depthWrite: false
      })
    );

    scene.add(marineSnow);

    // ---------------------------------------------------------------------
    // Direct camera controls: orbit, zoom, and reset
    // ---------------------------------------------------------------------

    let dragging = false;
    let previousX = 0;
    let previousY = 0;
    let autoRotate = true;

    function setAutoRotate(enabled) {
      autoRotate = enabled;
      rotateButton.textContent = enabled ? "Pause rotation" : "Resume rotation";
    }

    renderer.domElement.addEventListener("pointerdown", (event) => {
      dragging = true;
      previousX = event.clientX;
      previousY = event.clientY;
      renderer.domElement.setPointerCapture(event.pointerId);
      renderer.domElement.classList.add("dragging");
    });

    renderer.domElement.addEventListener("pointermove", (event) => {
      if (!dragging) return;

      const deltaX = event.clientX - previousX;
      const deltaY = event.clientY - previousY;

      previousX = event.clientX;
      previousY = event.clientY;

      cameraTheta -= deltaX * 0.006;
      cameraPhi = THREE.MathUtils.clamp(
        cameraPhi - deltaY * 0.005,
        0.35,
        1.46
      );

      updateCamera();
    });

    function stopDragging(event) {
      dragging = false;
      renderer.domElement.classList.remove("dragging");

      if (event.pointerId !== undefined && renderer.domElement.hasPointerCapture(event.pointerId)) {
        renderer.domElement.releasePointerCapture(event.pointerId);
      }
    }

    renderer.domElement.addEventListener("pointerup", stopDragging);
    renderer.domElement.addEventListener("pointercancel", stopDragging);
    renderer.domElement.addEventListener("contextmenu", (event) => event.preventDefault());

    renderer.domElement.addEventListener(
      "wheel",
      (event) => {
        event.preventDefault();
        cameraRadius = THREE.MathUtils.clamp(
          cameraRadius + event.deltaY * 0.008,
          7,
          18
        );
        updateCamera();
      },
      { passive: false }
    );

    rotateButton.addEventListener("click", () => {
      setAutoRotate(!autoRotate);
    });

    resetButton.addEventListener("click", () => {
      cameraTheta = 0.72;
      cameraPhi = 1.12;
      cameraRadius = 11.8;
      updateCamera();
    });

    // ---------------------------------------------------------------------
    // Resize and animation
    // ---------------------------------------------------------------------

    window.addEventListener("resize", () => {
      camera.aspect = window.innerWidth / window.innerHeight;
      camera.updateProjectionMatrix();

      renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
      renderer.setSize(window.innerWidth, window.innerHeight);
    });

    const clock = new THREE.Clock();

    renderer.setAnimationLoop(() => {
      const delta = Math.min(clock.getDelta(), 0.05);
      const elapsed = clock.elapsedTime;

      if (autoRotate && !dragging) {
        cameraTheta += delta * 0.055;
        updateCamera();
      }

      star.position.y = Math.sin(elapsed * 0.48) * 0.009;
      star.rotation.y = Math.sin(elapsed * 0.24) * 0.012;

      renderer.render(scene, camera);
    });
  </script>
</body>
</html>
